package ui08_pkg;
 import uvm_pkg::*; `include "uvm_macros.svh"
 class ui08_observation extends uvm_object; `uvm_object_utils(ui08_observation) int id; int payload; function new(string n="o");super.new(n);endfunction endclass
 class ui08_monitor extends uvm_component; `uvm_component_utils(ui08_monitor) uvm_analysis_port#(ui08_observation) ap; int published; function new(string n,uvm_component p);super.new(n,p);ap=new("ap",this);endfunction task run_phase(uvm_phase phase);ui08_observation item;for(int i=0;i<3;i++)begin item=ui08_observation::type_id::create("item");item.id=20+i;item.payload=(i+1)*3;ap.write(item);published++;end endtask endclass
 class ui08_subscriber extends uvm_subscriber#(ui08_observation); `uvm_component_utils(ui08_subscriber) int checks; function new(string n,uvm_component p);super.new(n,p);endfunction function void write(ui08_observation item);if((item.id!=20+checks)||(item.payload!=(checks+1)*3))`uvm_fatal("SUB","bad item") checks++;endfunction endclass
 class ui08_audit extends uvm_component; `uvm_component_utils(ui08_audit) uvm_analysis_imp#(ui08_observation,ui08_audit) in_imp;int checks;function new(string n,uvm_component p);super.new(n,p);in_imp=new("in_imp",this);endfunction function void write(ui08_observation item);if((item.id!=20+checks)||(item.payload!=(checks+1)*3))`uvm_fatal("AUDIT","bad item") checks++;endfunction endclass
 class ui08_env extends uvm_env; `uvm_component_utils(ui08_env) ui08_monitor monitor;ui08_subscriber subscriber;ui08_audit audit;function new(string n,uvm_component p);super.new(n,p);endfunction function void build_phase(uvm_phase phase);super.build_phase(phase);monitor=ui08_monitor::type_id::create("monitor",this);subscriber=ui08_subscriber::type_id::create("subscriber",this);audit=ui08_audit::type_id::create("audit",this);endfunction function void connect_phase(uvm_phase phase);super.connect_phase(phase);monitor.ap.connect(subscriber.analysis_export);monitor.ap.connect(audit.in_imp);endfunction endclass
 class ui08_test extends uvm_test; `uvm_component_utils(ui08_test) ui08_env env;function new(string n,uvm_component p);super.new(n,p);endfunction function void build_phase(uvm_phase phase);super.build_phase(phase);env=ui08_env::type_id::create("env",this);endfunction task run_phase(uvm_phase phase);phase.raise_objection(this);#1ns;if((env.monitor.published!=3)||(env.subscriber.checks!=3)||(env.audit.checks!=3))`uvm_fatal("COUNT",$sformatf("expected 3/3/3 got %0d/%0d/%0d",env.monitor.published,env.subscriber.checks,env.audit.checks)) $display("ANALYSIS_TRACE: published=%0d subscriber_checks=%0d audit_checks=%0d",env.monitor.published,env.subscriber.checks,env.audit.checks);$display("TEST_RESULT: PASS");phase.drop_objection(this);endtask endclass
